import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    This function finds the k-th largest element in an unsorted list using the Quickselect algorithm,
    which has an average time complexity of O(n) and a worst-case time complexity of O(n^2).
    """
    if k < 1 or k > len(nums):
        raise ValueError("k is out of bounds")

    def quickselect(left, right, k_smallest):
        if left == right:  # Only one element in the array
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_value = nums[pivot_index]

        # Move pivot to the end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        # Compare each element with the pivot
        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest, so use '>' for reverse order
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        # Move pivot to its final place
        nums[store_index], nums[right] = nums[right], nums[store_index]

        # Recursively apply the algorithm
        if k_smallest == store_index:
            return nums[store_index]
        elif k_smallest < store_index:
            return quickselect(left, store_index - 1, k_smallest)
        else:
            return quickselect(store_index + 1, right, k_smallest)

    # kth largest is the (len(nums) - k)th smallest
    return quickselect(0, len(nums) - 1, len(nums) - k)
